import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import VueApexCharts from "vue3-apexcharts";
import { prezence_daily_reports } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "PresenceDashboard",
  components: {
    apexchart: VueApexCharts
  },
  data() {
    const today = new Date();
    const formattedDate = `${String(today.getDate()).padStart(2, "0")}-${String(today.getMonth() + 1).padStart(2, "0")}-${today.getFullYear()}`;
    const isoFormattedDate = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
    return {
      formattedDate,
      isoFormattedDate,
      adminAppExists: false,
      tableLoading: false,
      windowHeight: 0,
      resenceData: [],
      leftCards: [],
      // initially empty, will be filled from API
      rightCards: [{
        label: "Configuration",
        icon: "mdi-cog-box",
        subtitle: "Configure attendance rules and presence settings.",
        route: "/home/Configuration",
        color: "#45B7D1"
      }, {
        label: "Data Correction",
        icon: "mdi-pencil-box",
        subtitle: "Update and correct attendance records for accuracy.",
        route: "/home/DataCorrection",
        color: "#FF6B6B"
      }, {
        label: "Reports",
        icon: "mdi-chart-box",
        subtitle: "Comprehensive reports for attendance and presence analysis.",
        route: "/home/AllReport",
        color: "#4ECDC4"
      },
      // {
      //   label: "Visitor Logs",
      //   icon: "mdi-clipboard-list",
      //   subtitle: "View and manage visitor entry and exit logs.",
      //   route: "/home/VisitLogs",
      //   color: "#45B7D1",
      // },
      {
        label: "Visitor",
        icon: "mdi-account-plus",
        subtitle: "Register and manage visitor entries and permissions.",
        route: "/home/VisitorSub",
        color: "#45B7D1"
      }],
      chartOptions: {
        chart: {
          type: "bar",
          toolbar: {
            show: false
          },
          fontFamily: "Inter, sans-serif"
        },
        plotOptions: {
          bar: {
            horizontal: false,
            columnWidth: "60%",
            endingShape: "rounded",
            borderRadius: 8,
            distributed: false
          }
        },
        dataLabels: {
          enabled: false
        },
        stroke: {
          show: true,
          width: 2,
          colors: ["transparent"]
        },
        xaxis: {
          categories: [],
          // Will be populated dynamically
          labels: {
            style: {
              colors: "#666",
              fontSize: "12px",
              fontFamily: "Inter, sans-serif"
            }
          },
          axisBorder: {
            show: false
          },
          axisTicks: {
            show: false
          }
        },
        yaxis: {
          title: {
            text: "Number of Employees",
            style: {
              color: "#666",
              fontSize: "14px",
              fontFamily: "Inter, sans-serif"
            }
          },
          labels: {
            style: {
              colors: "#666",
              fontSize: "12px",
              fontFamily: "Inter, sans-serif"
            }
          }
        },
        legend: {
          position: "top",
          horizontalAlign: "right",
          fontSize: "14px",
          fontFamily: "Inter, sans-serif",
          markers: {
            radius: 12
          },
          itemMargin: {
            horizontal: 10
          }
        },
        colors: ["#4CAF50", "#F44336", "#2196F3"],
        grid: {
          borderColor: "#f1f1f1",
          strokeDashArray: 4
        },
        tooltip: {
          y: {
            formatter: function (val) {
              return val + " employees";
            }
          },
          theme: "dark",
          style: {
            fontSize: "12px",
            fontFamily: "Inter, sans-serif"
          }
        },
        responsive: [{
          breakpoint: 768,
          options: {
            plotOptions: {
              bar: {
                columnWidth: "80%"
              }
            },
            legend: {
              position: "bottom"
            }
          }
        }]
      },
      chartSeries: [] // Will be populated dynamically
    };
  },
  created() {
    this.$store.commit("SetattendenceBack", false);
    this.windowHeight = window.innerHeight - 10;
    this.fetch_admin_apps();
    this.presence_reports();
  },
  methods: {
    back_call() {
      this.$router.push("/home/UserLevel");
    },
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;
      const userapp = userObj.user_apps.find(app => app.dashboard_unique_type == "PREZENCE");
      if (userapp == undefined) {
        this.adminAppExists = false;
        return;
      }
      if (userapp.is_visible == false) {
        this.adminAppExists = false;
        return;
      }
      // Check if userObj and admin_apps exist
      if (!userObj || !userObj.admin_apps || !Array.isArray(userObj.admin_apps)) {
        this.adminAppExists = false;
        return;
      }
      const adminExists = userObj.admin_apps.find(app => app.dashboard_unique_type === "PREZENCE_ADMINS");
      this.adminAppExists = adminExists && (adminExists.app_usage_level === "WEB_PHONE_ONLY" || adminExists.app_usage_level === "WEB_ONLY") && adminExists.is_dashboard_admin === true;
    },
    getTotalPresent() {
      return this.leftCards.find(card => card.label === "Present")?.value || 0;
    },
    getTotalAbsent() {
      return this.leftCards.find(card => card.label === "Absent")?.value || 0;
    },
    getTotalLeave() {
      return this.leftCards.find(card => card.label === "Leave")?.value || 0;
    },
    getCardSubtitle(label) {
      const subtitles = {
        All: "Total employees tracked",
        Present: "Employees present today",
        Absent: "Employees absent today",
        Leave: "Employees on leave today"
      };
      return subtitles[label] || "";
    },
    handleCardClick(label) {
      const routeMap = {
        All: "/home/SwipeLogs",
        Present: "/home/PresentReport",
        Absent: "/home/AbsentReport",
        Leave: "/home/LeaveReport"
      };
      const route = routeMap[label];
      if (route) this.$router.push(route);else console.warn(`No route defined for label: ${label}`);
    },
    handleRightCardClick(route) {
      if (route) this.$router.push(route);else console.warn("No route defined for this card");
    },
    async presence_reports() {
      this.tableLoading = true;
      try {
        const result = await API.graphql(graphqlOperation(prezence_daily_reports, {
          input: {
            swipe_date: this.isoFormattedDate,
            action_type: "ALL"
          }
        }));
        this.tableLoading = false;
        const response = JSON.parse(result.data.prezence_daily_reports);
        if (response.Status === "SUCCESS") {
          const data = response.graph_data;

          // Dynamic values for cards
          const total = data.total || {
            P: 0,
            A: 0,
            L: 0
          };
          const present = total.P || 0;
          const absent = total.A || 0;
          const leave = total.L || 0;
          const all = present + absent + leave;
          this.resenceData = total;
          this.leftCards = [{
            label: "All",
            value: all,
            icon: "mdi-account-group",
            color: "#3F51B5"
          }, {
            label: "Present",
            value: present,
            icon: "mdi-account-check",
            color: "#4CAF50"
          }, {
            label: "Absent",
            value: absent,
            icon: "mdi-account-remove",
            color: "#F44336"
          }, {
            label: "Leave",
            value: leave,
            icon: "mdi-account-clock",
            color: "#2196F3"
          }];

          // Build chart
          const labels = [];
          const presentData = [];
          const absentData = [];
          const leaveData = [];
          for (const [key, value] of Object.entries(data)) {
            if (key === "total") continue;
            labels.push(value.name || key); // Use value.name for custom labels
            presentData.push(value.P || 0);
            absentData.push(value.A || 0);
            leaveData.push(value.L || 0);
          }

          // Update chartOptions and chartSeries
          this.chartOptions = {
            ...this.chartOptions,
            xaxis: {
              ...this.chartOptions.xaxis,
              categories: labels // Set dynamic labels
            }
          };
          this.chartSeries = [{
            name: "Present",
            data: presentData
          }, {
            name: "Absent",
            data: absentData
          }, {
            name: "Leave",
            data: leaveData
          }];
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Something went wrong",
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
